{
  "info": {
    "title": "UAE Account Information API",
    "description": "## UAE Open Finance Account Information API Specification",
    "version": "v2.2-rc2"
  },
  "servers": [
    {
      "url": "/open-finance/account-information/v2.2"
    }
  ],
  "source_path": "/account-access-consents/{ConsentId}/attestations",
  "operations": {
    "get": {
      "operationId": "ReadAccountAccessConsentAttestations",
      "summary": "Retrieve attestations",
      "description": "Retrieve the Attestation Events recorded against a consent for a given `ConsentId`.\n\nAll successfully recorded Attestation Events are returned, each carrying a copy of the\nAttestation submitted by the TPP. Where the TPP has submitted more than one Attestation\nfor the consent, only the last successfully recorded Attestation is reported on.\n\nThe `LastSubmitted` parameter can be used to retrieve only the last successfully recorded\nAttestation Event.",
      "parameters": [
        {
          "$ref": "#/components/parameters/Authorization"
        },
        {
          "$ref": "#/components/parameters/x-customer-user-agent"
        },
        {
          "$ref": "#/components/parameters/x-fapi-auth-date"
        },
        {
          "$ref": "#/components/parameters/x-fapi-customer-ip-address"
        },
        {
          "$ref": "#/components/parameters/x-fapi-interaction-id"
        },
        {
          "$ref": "#/components/parameters/ConsentId"
        },
        {
          "$ref": "#/components/parameters/LastSubmitted"
        }
      ],
      "responses": {
        "200": {
          "description": "The request has succeeded.",
          "headers": {
            "x-fapi-interaction-id": {
              "required": false,
              "description": "An RFC4122 UID used as a correlation ID.",
              "schema": {
                "type": "string"
              }
            }
          },
          "content": {
            "application/json; charset=utf-8": {
              "schema": {
                "$ref": "#/components/schemas/AETPPAttestations1Response"
              }
            },
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/AETPPAttestations1Response"
              }
            }
          }
        },
        "400": {
          "$ref": "#/components/responses/400Error"
        },
        "401": {
          "$ref": "#/components/responses/401Error"
        },
        "403": {
          "$ref": "#/components/responses/403Error"
        },
        "404": {
          "$ref": "#/components/responses/404Error"
        },
        "405": {
          "$ref": "#/components/responses/405Error"
        },
        "406": {
          "$ref": "#/components/responses/406Error"
        },
        "415": {
          "$ref": "#/components/responses/415Error"
        },
        "429": {
          "$ref": "#/components/responses/429Error"
        },
        "500": {
          "$ref": "#/components/responses/500Error"
        }
      },
      "tags": [
        "Bank Data Sharing Consent"
      ],
      "security": [
        {
          "TPPOAuth2Security": [
            "accounts"
          ]
        }
      ]
    }
  }
}

{
  "name": "authorization",
  "in": "header",
  "required": true,
  "description": "An authorization Token as per https://tools.ietf.org/html/rfc6750",
  "schema": {
    "type": "string"
  }
}

{
  "in": "header",
  "name": "x-customer-user-agent",
  "description": "Indicates the user-agent that the User is using.",
  "required": false,
  "schema": {
    "type": "string"
  }
}

{
  "in": "header",
  "name": "x-fapi-auth-date",
  "required": false,
  "description": "The time when the User last logged in with the TPP. \nAll dates in the HTTP headers are represented as RFC 7231 Full Dates. An example is below: \nSun, 10 Sep 2017 19:43:31 UTC",
  "schema": {
    "type": "string",
    "pattern": "^(Mon|Tue|Wed|Thu|Fri|Sat|Sun), \\d{2} (Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec) \\d{4} \\d{2}:\\d{2}:\\d{2} (GMT|UTC)$"
  }
}

{
  "in": "header",
  "name": "x-fapi-customer-ip-address",
  "required": false,
  "description": "The User's IP address if the User is currently logged in with the TPP.",
  "schema": {
    "type": "string"
  }
}

{
  "in": "header",
  "name": "x-fapi-interaction-id",
  "required": false,
  "description": "An RFC4122 UID used as a correlation id.",
  "schema": {
    "type": "string"
  }
}

{
  "name": "ConsentId",
  "in": "path",
  "description": "ConsentId",
  "required": true,
  "schema": {
    "type": "string"
  }
}

{
  "name": "LastSubmitted",
  "in": "query",
  "required": false,
  "description": "If `true`, only the last successfully recorded Attestation Event submitted by the TPP is returned.\n\nThis is the Attestation Event that is reported on for the consent.",
  "schema": {
    "type": "boolean",
    "default": false
  },
  "explode": false
}

{
  "type": "object",
  "required": [
    "Data",
    "Links",
    "Meta"
  ],
  "properties": {
    "Data": {
      "type": "array",
      "items": {
        "$ref": "#/components/schemas/AETPPAttestation1Properties"
      },
      "description": "The Attestation Events recorded against the consent.\n\nEach item includes a copy of the Attestation submitted by the TPP."
    },
    "Links": {
      "$ref": "#/components/schemas/LinksResource"
    },
    "Meta": {
      "$ref": "#/components/schemas/MetaTotalPages"
    }
  },
  "additionalProperties": false
}

{
  "type": "object",
  "required": [
    "AttestationId",
    "AttestationReceivedDateTime",
    "RegulatoryDeadlineMetIndicator",
    "Attestation"
  ],
  "properties": {
    "AttestationId": {
      "description": "A unique identifier for the Attestation submitted by the TPP.",
      "type": "string",
      "format": "uuid"
    },
    "AttestationReceivedDateTime": {
      "allOf": [
        {
          "$ref": "#/components/schemas/AEDateTime"
        },
        {
          "description": "Date and time at which the API Hub received the Attestation."
        }
      ]
    },
    "RegulatoryDeadlineMetIndicator": {
      "type": "boolean",
      "description": "Indicates whether the API Hub received the Attestation prior to the regulatory deadline for the `AttestationType` being submitted."
    },
    "Attestation": {
      "allOf": [
        {
          "$ref": "#/components/schemas/AETPPAttestation1Types"
        }
      ],
      "description": "A copy of the Attestation submitted by the TPP, as recorded by the API Hub.\n\nThis is included so that the complete record of the Attestation is incorporated in the message signature."
    }
  },
  "additionalProperties": false
}

{
  "type": "object",
  "allOf": [
    {
      "$ref": "#/components/schemas/AETPPDataRetentionDeletionAttestation1Properties"
    }
  ],
  "description": "The Attestation being submitted.\n\nAt this version the only permitted type is `DataRetentionDeletion`, a Data Retention or Deletion Attestation."
}

{
  "type": "object",
  "required": [
    "AttestationType",
    "AttestationStatusAppliedDateTime",
    "DataAccessCeasedDateTime",
    "DataActions"
  ],
  "properties": {
    "AttestationType": {
      "allOf": [
        {
          "$ref": "#/components/schemas/AETPPAttestationType1Codes"
        }
      ],
      "description": "The Attestation Type, with the value `DataRetentionDeletion` to indicate an attestation on data retention for consented data held by the TPP."
    },
    "AttestationStatusAppliedDateTime": {
      "allOf": [
        {
          "$ref": "#/components/schemas/AEDateTime"
        },
        {
          "description": "Date and time at which the Attestation is valid from. This must be in the past."
        }
      ]
    },
    "DataAccessCeasedDateTime": {
      "allOf": [
        {
          "$ref": "#/components/schemas/AEDateTime"
        },
        {
          "description": "Date and time at which TPP data access ceased. This must be in the past."
        }
      ]
    },
    "ConsentRevocationDateTime": {
      "allOf": [
        {
          "$ref": "#/components/schemas/AEDateTime"
        },
        {
          "description": "Date and time at which the User revoked the Consent at the TPP.\n\nOnly provided where the consent was revoked at the TPP, and did not expire or was not consumed.\nWhere provided this must be in the past, and earlier than the date and time at which the consent\nwas revoked at the API Hub."
        }
      ]
    },
    "DataActions": {
      "type": "array",
      "items": {
        "$ref": "#/components/schemas/AEAccountAccessTPPAttestationDataAction1Properties"
      },
      "minItems": 1,
      "description": "The actions taken by the TPP for each category of data held.\n\nAn Attestation Event must list all `DataCategory` values that apply to the consent."
    }
  },
  "description": "An attestation by the TPP that it has completed the review, and any required deletion or anonymisation,\nof data associated with the consent that it is not required or otherwise permitted to retain.",
  "additionalProperties": false
}

{
  "type": "string",
  "enum": [
    "DataRetentionDeletion"
  ],
  "description": "The Attestation Type, indicating the regulatory obligation to which the Attestation relates.\n\n* `DataRetentionDeletion`: An attestation on data retention and deletion for consented data held by the TPP."
}

{
  "type": "object",
  "required": [
    "DataActionType",
    "DataCategory",
    "AttestationDate"
  ],
  "properties": {
    "DataActionType": {
      "allOf": [
        {
          "$ref": "#/components/schemas/AETPPAttestationDataAction1Codes"
        }
      ],
      "description": "The action taken by the TPP for the category of data indicated by `DataCategory`.\n\nThe value `Deleted` is an attestation that the data has been deleted by the TPP.\nThe values `Retained`, `Anonymised` and `ArchivedRestricted` are attestations that the data is retained in some form."
    },
    "DataCategory": {
      "allOf": [
        {
          "$ref": "#/components/schemas/AEAccountAccessTPPAttestationDataCategory1Codes"
        }
      ],
      "description": "The category of data to which the attestation applies."
    },
    "AttestationDate": {
      "allOf": [
        {
          "$ref": "#/components/schemas/AEDateTime"
        },
        {
          "description": "Date and time at which the attestation for the data category is made.\n\nThis must be in the past, later than `ConsentRevocationDateTime` where provided, and earlier than\n`AttestationStatusAppliedDateTime`."
        }
      ]
    },
    "RetentionReason": {
      "allOf": [
        {
          "$ref": "#/components/schemas/AETPPAttestationRetentionReason1Codes"
        }
      ],
      "description": "Indicates the reason for retaining the consented data.\n\nMust be provided where `DataActionType` is `Retained`, `Anonymised` or `ArchivedRestricted`."
    },
    "RetentionReasonDescription": {
      "type": "string",
      "minLength": 1,
      "maxLength": 500,
      "description": "The reason for retaining the data.\n\nMust be provided where `DataActionType` is `Retained`, `Anonymised` or `ArchivedRestricted` and\n`RetentionReason` is `Other`."
    },
    "RetainedUntilDate": {
      "type": "string",
      "format": "date",
      "description": "The date until which the TPP will retain the data. This must be in the future.\n\nMust be provided where `DataActionType` is `Retained`, `Anonymised` or `ArchivedRestricted`."
    },
    "AccessRestriction": {
      "allOf": [
        {
          "$ref": "#/components/schemas/AETPPAttestationAccessRestriction1Codes"
        }
      ],
      "description": "Indicates how access is restricted to the retained data.\n\nMust be provided where `DataActionType` is `Retained`, `Anonymised` or `ArchivedRestricted`."
    },
    "AccessRestrictionDescription": {
      "type": "string",
      "minLength": 1,
      "maxLength": 500,
      "description": "A description of how access to the data is restricted.\n\nMust be provided where `DataActionType` is `ArchivedRestricted` and `AccessRestriction` is `Other`."
    }
  },
  "additionalProperties": false
}

{
  "type": "string",
  "enum": [
    "Deleted",
    "Retained",
    "Anonymised",
    "ArchivedRestricted"
  ],
  "description": "The action taken by the TPP for the category of data indicated by `DataCategory`, with the following definitions:\n\n* `Deleted`: The data has been deleted by the TPP.\n\n* `Retained`: The data is retained by the TPP in its original form.\n\n* `Anonymised`: The data is retained by the TPP in an effectively anonymised form.\n\n* `ArchivedRestricted`: The data is retained by the TPP in an archive to which access is restricted."
}

{
  "type": "string",
  "enum": [
    "NotRestricted",
    "RestrictedUseOnly",
    "Other"
  ],
  "description": "Indicates how access is restricted to the retained data, with the following definitions:\n\n* `NotRestricted`: Access to the retained data is not restricted.\n\n* `RestrictedUseOnly`: The retained data may only be accessed for the purpose indicated by `RetentionReason`.\n\n* `Other`: Access is restricted in another way, which must be described in `AccessRestrictionDescription`."
}

{
  "type": "object",
  "required": [
    "Self"
  ],
  "properties": {
    "Self": {
      "$ref": "#/components/schemas/Self"
    },
    "First": {
      "$ref": "#/components/schemas/First"
    },
    "Prev": {
      "$ref": "#/components/schemas/Prev"
    },
    "Next": {
      "$ref": "#/components/schemas/Next"
    },
    "Last": {
      "$ref": "#/components/schemas/Last"
    }
  },
  "description": "Links relevant to the resource",
  "additionalProperties": false
}

{
  "description": "A link to the current resource",
  "type": "string",
  "format": "uri"
}

{
  "description": "A link to the first page in a paginated result set",
